create table if not exists reconnect_log (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, user_id uuid, disconnected_at timestamptz not null, reconnected_at timestamptz, duration_seconds int default 0, reason text, created_at timestamptz default now()); alter table reconnect_log enable row level security; create index if not exists idx_reconnect_room_user on reconnect_log(room_id,user_id);
